pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 sendValue) public {
        // Ensure sendValue is positive to trigger the bug (zero would pass by chance)
        vm.assume(sendValue > 0);
        // Set initial balance for the sender via deal (no internal setter)
        vm.deal(sender, sendValue); // give sender eth to send
        // We can't set userBalance directly, but we can call addToBalance multiple times or handle via deal?
        // Actually, userBalance starts at 0 for everyone. To have a non-zero initial balance, we need a prior deposit.
        // We'll call addToBalance once with a large deposit from sender to give them a balance.
        vm.prank(sender);
        c.addToBalance{value: initialBalance}();
        // Now sender has initialBalance (plus possibly leftover) - but that's set via public function

        // Now call addToBalance with sendValue
        vm.prank(sender);
        bool success = address(c).call{value: sendValue}(abi.encodeWithSelector(c.addToBalance.selector));

        // If reference, after call balance should be initialBalance + sendValue > 0
        // If buggy, balance becomes sendValue (since reset to 0 then add)
        // Since sendValue > 0, balance is never 0 in reference, but could be 0 only if buggy version zeros it before...
        // Actually bug: userBalance = 0 then = 0 + sendValue = sendValue > 0. So zero only if sendValue==0, which we assume>0.
        // This rule won't catch the bug. We need a different property.
        // 
        // Correct rule: The sum of all user balances should equal contract's balance after successive deposits.
        // But we only test one user. Let's use property: after addToBalance, the caller's balance does NOT decrease.
        // Reference: new balance = old balance + msg.value >= old balance. Bug: new balance = msg.value, which < old balance if old>0.
        // So assert that balance does not decrease.

        uint256 newBalance = c.getBalance(sender);
        assertTrue(newBalance >= initialBalance, "Balance should not decrease");
    }
}

