// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        vm.assume(amount <= address(this).balance);

        // Deploy a contract that can selfdestruct to send ETH
        address attacker = address(new Attacker());

        // Fund the caller if needed
        vm.deal(caller, amount);

        // Call addToBalance from caller
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // Record balance after first call
        uint256 balanceAfterFirst = c.getBalance(caller);

        // Selfdestruct ETH to the contract (mimicking a forced ETH send)
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool success, ) = address(new Attacker()).call{value: amount}("");
        require(success);

        // Call addToBalance again from same caller
        vm.deal(caller, 0); // no additional ETH
        vm.prank(caller);
        c.addToBalance();

        // The bug (missing lock update) could cause the second addToBalance to be reentered
        // and increment balance despite no msg.value sent. This assertion checks that
        // the balance after the second call is exactly the amount first sent (no phantom increase)
        uint256 balanceAfterSecond = c.getBalance(caller);
        assertTrue(balanceAfterSecond == amount, "Balance should not increase from selfdestruct ETH");
    }
}

contract Attacker {
    receive() external payable {
        // selfdestruct to send ETH to C contract
        selfdestruct(payable(address(this)));
    }
}
